package com.learnagent.skill;
import com.learnagent.agent.AgentExecutionTracker;import com.learnagent.planning.PlanningService;import java.time.Instant;import java.util.*;import org.springframework.ai.tool.annotation.*;import org.springframework.stereotype.Component;
@Component public class PlanningSkill{private final PlanningService service;private final AgentExecutionTracker tracker;public PlanningSkill(PlanningService service,AgentExecutionTracker tracker){this.service=service;this.tracker=tracker;}@Tool(description="Generate a proposed study plan from a goal and weak points. This does not create tasks; call createTask for every task the user wants saved.")public PlanResult generateStudyPlan(@ToolParam(description="Study planning input")PlanInput input){return tracker.execute("Planning Skill","generateStudyPlan",()->{var plan=service.generate(input.courseId(),input.goal(),input.weakPoints()==null?List.of():input.weakPoints(),input.deadline()==null||input.deadline().isBlank()?null:Instant.parse(input.deadline()));return new PlanResult(plan.courseId(),plan.goal(),plan.items().stream().map(x->new PlanItem(x.topic(),x.scheduledAt(),x.estimatedMinutes(),x.objective())).toList());},value->"Generated plan with "+value.items().size()+" items");}public record PlanInput(UUID courseId,String goal,List<String> weakPoints,String deadline){}public record PlanResult(UUID courseId,String goal,List<PlanItem> items){}public record PlanItem(String topic,Instant scheduledAt,int estimatedMinutes,String objective){}
}
